document.addEventListener("DOMContentLoaded",function(){iniciarMenuMobile();const s=document.createElement("style");s.textContent=`
        .feed-item {
            opacity: 0;
            transform: translateY(24px);
            transition: opacity 0.55s ease, transform 0.55s ease;
        }
        .feed-item.visible {
            opacity: 1;
            transform: translateY(0);
        }
        /* Respeita prefer\xEAncia de acessibilidade */
        @media (prefers-reduced-motion: reduce) {
            .feed-item {
                opacity: 1;
                transform: none;
                transition: none;
            }
        }
    `,document.head.appendChild(s);const a=document.querySelectorAll(".feed-item"),i=new IntersectionObserver(function(t){t.forEach(function(e){e.isIntersecting&&(e.target.classList.add("visible"),i.unobserve(e.target))})},{threshold:.15});a.forEach(function(t,e){const n=Math.min(e*80,320);t.style.transitionDelay=n+"ms",i.observe(t)});const o=document.getElementById("feed");o&&o.addEventListener("click",function(t){const e=t.target.closest(".btn");if(!e)return;const n=e.closest(".feed-item"),c=n?n.querySelector(".feed-title")?.textContent:"Desconhecido";e.classList.contains("btn-primary"),e.classList.contains("btn-secondary")})});
